SELECT


WHERE o.deleted = 0

    AND (cc.course_name LIKE CONCAT('%', #{q.keyword}, '%')
    OR cc.course_code LIKE CONCAT('%', #{q.keyword}, '%')
    OR o.offering_code LIKE CONCAT('%', #{q.keyword}, '%')
    OR t.name LIKE CONCAT('%', #{q.keyword}, '%'))

AND o.semester_id = #{q.semesterId}
AND o.teacher_id = #{q.teacherId}
AND o.class_id = #{q.classId}
AND o.course_id = #{q.courseId}
AND o.is_public = #{q.isPublic}
AND o.status = #{q.status}
ORDER BY o.semester_id DESC, o.is_public ASC, o.id ASC

SELECT


WHERE o.deleted = 0 AND o.teacher_id = #{teacherId}
AND o.semester_id = #{semesterId}
ORDER BY o.id ASC

SELECT


WHERE o.deleted = 0 AND o.class_id = #{classId}
AND o.semester_id = #{semesterId}
ORDER BY o.id ASC

SELECT
WHERE o.deleted = 0 AND o.status = 1 AND (o.is_public = 1
OR o.class_id = #{classId}
) AND NOT EXISTS ( SELECT 1 FROM course_selection sel WHERE sel.offering_id = o.id AND sel.student_id = #{studentId} AND sel.status = 1 ) AND o.semester_id = #{semesterId}
AND (cc.course_name LIKE CONCAT('%', #{keyword}, '%') OR cc.course_code LIKE CONCAT('%', #{keyword}, '%') OR t.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.is_public ASC, cc.course_code ASC
